"""Summarize revenue by region."""


def summarize(rows):
    """Aggregate revenue per region.

    Args:
        rows: list of dicts, each with keys 'region' and 'revenue'.
              'revenue' may be a number or a numeric string.

    Returns:
        dict mapping region -> total revenue (float). Rows whose revenue is
        missing or cannot be parsed as a float are ignored.
    """
    totals = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        region = row.get("region")
        if region is None:
            continue
        value = row.get("revenue")
        if value is None:
            continue
        try:
            total_value = float(value)
        except (TypeError, ValueError):
            continue
        totals[region] = totals.get(region, 0.0) + total_value
    return totals

