"""Summarize total revenue per region.

Usage:
    python summarize.py
    # reads rows from stdin as JSON, or a CSV file with headers region,revenue
    python summarize.py data.csv
"""
import csv
import json
import sys


def _to_float(value):
    """Convert value to float, or return None if unparseable."""
    if value is None:
        return None
    try:
        return float(str(value).strip())
    except (ValueError, TypeError):
        return None


def summarize(rows):
    """Sum revenue per region.

    Args:
        rows: list of dicts, each with keys 'region' and 'revenue'.

    Returns:
        dict mapping region -> total revenue (float). Rows whose revenue is
        missing or unparseable are ignored.
    """
    totals = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        region = row.get("region")
        if region is None or str(region).strip() == "":
            continue
        revenue = _to_float(row.get("revenue"))
        if revenue is None:
            continue
        totals[region] = totals.get(region, 0.0) + revenue
    return totals


def main():
    if len(sys.argv) > 1:
        with open(sys.argv[1], newline="") as f:
            rows = list(csv.DictReader(f))
    else:
        rows = json.loads(sys.stdin.read())

    result = summarize(rows)
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

