"""Parse a 'key=value; key2=value2' string into a dict."""


def parse_kv(s):
    """Parse s of the form 'key1=value1; key2=value2'.

    - Semicolons separate pairs.
    - The first '=' separates key from value.
    - Keys and values are whitespace-trimmed.
    - A backslash-escaped semicolon (\\;) is a literal semicolon in the value.
    - An empty string yields an empty dict.
    """
    result = {}
    i = 0
    n = len(s)

    while i < n:
        # Find the next unescaped semicolon to determine this pair's extent.
        j = i
        while j < n and s[j] != ';':
            if s[j] == '\\' and j + 1 < n:
                j += 2  # skip escaped character (e.g. \;)
            else:
                j += 1
        segment = s[i:j]
        i = j + 1  # move past the semicolon (or end of string)

        if not segment.strip():
            continue  # ignore empty segments, e.g. trailing ';'

        if '=' not in segment:
            raise ValueError(f"Invalid pair (missing '='): {segment!r}")

        key, value = segment.split('=', 1)
        result[key.strip()] = value.strip()

    return result


if __name__ == "__main__":
    import sys
    for line in sys.argv[1:]:
        print(parse_kv(line))

import pytest
from parse_kv import parse_kv


def test_empty_string():
    assert parse_kv("") == {}


def test_simple_single_pair():
    assert parse_kv("a=b") == {"a": "b"}


def test_multiple_pairs():
    assert parse_kv("key1=value1; key2=value2") == {
        "key1": "value1",
        "key2": "value2",
    }


def test_whitespace_trimmed():
    assert parse_kv("  key   =   value   ") == {"key": "value"}


def test_spaces_around_semicolon():
    assert parse_kv("a=1;  b=2 ; c=3") == {"a": "1", "b": "2", "c": "3"}


def test_empty_segments_are_ignored():
    assert parse_kv("a=1;;b=2") == {"a": "1", "b": "2"}
    assert parse_kv("a=1;") == {"a": "1"}


def test_backslash_escaped_semicolon_in_value():
    # A literal semicolon in the value does not split the pair.
    assert parse_kv("k=v\\;x") == {"k": "v;x"}


def test_multiple_escaped_semicolons():
    assert parse_kv("a=1\\;2\\;3; b=4") == {"a": "1;2;3", "b": "4"}


def test_first_equals_only_splits_key_and_value():
    # Everything after the first '=' is the value, even if it contains '='.
    assert parse_kv("k=a=b=c") == {"k": "a=b=c"}


def test_value_with_equals_and_escaped_semicolon():
    assert parse_kv("url=http://x?a=1\\;b=2") == {
        "url": "http://x?a=1;b=2"
    }


def test_key_with_spaces_trimmed_but_internal_kept():
    # Internal spaces in the key are preserved, only trimmed at edges.
    assert parse_kv("my key =  v ") == {"my key": "v"}


def test_backslash_at_end_of_value_is_preserved():
    # A trailing backslash is not an escape (nothing follows it).
    assert parse_kv("a=b\\") == {"a": "b\\"}


def test_escaped_backslash_then_semicolon_splts_pair():
    # "\\" is a literal backslash, so the following ';' still splits.
    assert parse_kv("a=x\\; b=2") == {"a": "x;", "b": "2"}


def test_missing_equals_raises():
    with pytest.raises(ValueError):
        parse_kv("noequals")


def test_repeated_keys_last_wins():
    assert parse_kv("k=1; k=2") == {"k": "2"}

