def _unescape(value):
    """Replace backslash-escaped semicolons (\\;) with literal ';'.

    Any other character following a backslash is left as-is, so the
    result preserves whatever follows the backslash.
    """
    out = []
    i = 0
    n = len(value)
    while i < n:
        c = value[i]
        if c == '\\' and i + 1 < n:
            nxt = value[i + 1]
            if nxt == ';':
                out.append(';')
            else:
                # Not an escape we care about; keep the backslash as-is.
                out.append(c)
            i += 2
        else:
            out.append(c)
            i += 1
    return ''.join(out)


def parse_kv(s):
    """Parse s of the form 'key1=value1; key2=value2'.

    - Semicolons separate pairs.
    - The first '=' separates key from value.
    - Keys and values are whitespace-trimmed.
    - A backslash-escaped semicolon (\\;) is a literal semicolon in the value.
    - An empty string yields an empty dict.
    """
    result = {}
    i = 0
    n = len(s)

    while i < n:
        # Find the next unescaped semicolon to determine this pair's extent.
        j = i
        while j < n and s[j] != ';':
            if s[j] == '\\' and j + 1 < n:
                j += 2  # skip an escaped character (e.g. \;)
            else:
