import pytest
from parse_kv import parse_kv


def test_empty_string():
    assert parse_kv("") == {}


def test_single_pair():
    assert parse_kv("a=b") == {"a": "b"}


def test_multiple_pairs():
    assert parse_kv("key1=value1; key2=value2") == {"key1": "value1", "key2": "value2"}


def test_whitespace_trimmed():
    assert parse_kv("  key1  =   value1  ;  key2 = value2  ") == {
        "key1": "value1",
        "key2": "value2",
    }


def test_escaped_semicolon_in_value():
    # The \; is a literal semicolon in the value, not a pair separator.
    assert parse_kv("a=b\\;c") == {"a": "b;c"}


def test_escaped_semicolon_not_splitting_pairs():
    assert parse_kv("x=1\\;2; y=3") == {"x": "1;2", "y": "3"}


def test_backslash_before_non_semicolon_is_literal():
    # A backslash only escapes a semicolon; otherwise it stays as-is.
    assert parse_kv("a=b\\c") == {"a": "b\\c"}


def test_value_with_equals_sign():
    # Only the first '=' separates key and value.
    assert parse_kv("url=http://x?a=1&b=2") == {"url": "http://x?a=1&b=2"}


def test_key_only_no_value():
    # A part without '=' is ignored (no key/value split possible).
    assert parse_kv("a=b; c") == {"a": "b"}


def test_empty_pair_between_semicolons():
    assert parse_kv("a=b;;c=d") == {"a": "b", "c": "d"}


def test_only_whitespace_between_pairs():
    assert parse_kv("a=b;   ; c=d") == {"a": "b", "c": "d"}


def test_escaped_semicolon_in_key():
    # Escaped semicolons can also appear in keys.
    assert parse_kv("a\\;b=c") == {"a;b": "c"}


def test_value_with_leading_trailing_spaces_inside_trimmed():
    # Inner spaces around '=' are trimmed on both sides.
    assert parse_kv(" k = v ") == {"k": "v"}


def test_escaped_semicolon_at_end_of_value():
    assert parse_kv("a=b\\;") == {"a": "b;"}


def test_multiple_escaped_semicolons():
    assert parse_kv("a=1\\;2\\;3") == {"a": "1;2;3"}


def test_no_equals_in_any_pair():
    assert parse_kv("foo; bar") == {}


def test_value_is_empty_after_trim():
    assert parse_kv("k=") == {"k": ""}


def test_semicolon_only_input():
    assert parse_kv(";") == {}

